            {
                float s = 0;
                for (int i = 0; i < dense.M_Rows; i++) s += dense[i, j] * x[i];
                y[j] = s;
            }
        }

        // SPD b x b block D = M^T M + b*I: symmetric, well-conditioned -> LU-invertible, and
        // D_i z_i == r_i holds tightly.
        static floatMxN SpdBlock(int b, uint seed)
        {
