            float d1 = op.ApplyDot(in x, ref y1);

            var y2 = new floatN(rows, Allocator.Temp);
            op.Apply(in x, ref y2);
            float d2 = Blas.dot(x, y2);

            AssertExactVec(in y1, in y2);
            Assert.AreEqual((double)d2, (double)d1);   // bit-exact scalar
        }

